def ultrafilter_decide(prop, N=100000, threshold=0.9):
    count = sum(1 for i in range(N) if prop(i))
    return count / N > threshold

def compare(f, g, N=10000, t=0.9):
    lt = sum(1 for i in range(N) if f(i) < g(i))
    return 'f < g' if lt/N > t else 'indeterminate'

def find_threshold(prop, max_search=100000):
    for n in range(max_search, -1, -1):
        if not prop(n): return n + 1
    return 0
